document.addEventListener('DOMContentLoaded',function(){const root=document.getElementById('et-user-management-103175');if(!root)return;const search=document.getElementById('et-user-search-103336'),branch=document.getElementById('et-branch-filter-103336');const filter=()=>{const q=(search?.value||'').toLowerCase().trim(),b=branch?.value||'';root.querySelectorAll('[data-user-row]').forEach(row=>{row.style.display=(!q||row.dataset.search.includes(q))&&(!b||(','+row.dataset.branches+',').includes(','+b+','))?'':'none';});};search?.addEventListener('input',filter);branch?.addEventListener('change',filter);const psearch=document.getElementById('et-permission-search-103335');psearch?.addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();root.querySelectorAll('[data-permission-row]').forEach(row=>row.style.display=!q||row.dataset.search.includes(q)?'':'none';});document.getElementById('et-expand-all-103336')?.addEventListener('click',()=>root.querySelectorAll('.um-perm-section').forEach(x=>x.open=true));document.getElementById('et-collapse-all-103336')?.addEventListener('click',()=>root.querySelectorAll('.um-perm-section').forEach(x=>x.open=false));root.querySelectorAll('.et-section-select-all-103335').forEach(select=>select.addEventListener('change',()=>{root.querySelectorAll('[data-permission-checkbox][data-section="'+CSS.escape(select.dataset.section)+'"]').forEach(box=>box.checked=select.checked);refresh();}));const refresh=()=>root.querySelectorAll('[data-permission-section]').forEach(section=>{const boxes=[...section.querySelectorAll('[data-permission-checkbox]')],selected=boxes.filter(box=>box.checked).length,all=boxes.length>0&&selected===boxes.length,select=section.querySelector('.et-section-select-all-103335');if(select){select.checked=all;select.indeterminate=selected>0&&!all;}});const templates=@json($roleTemplates),template=document.getElementById('et-role-template-103335'),state=document.getElementById('et-template-state-103335');const applyTemplate=()=>{if(template.value==='Custom Access'){if(state)state.textContent='Custom Access · Customized';return;}if(state)state.textContent=template.value;};document.getElementById('et-apply-template-103335')?.addEventListener('click',applyTemplate);document.getElementById('et-reset-template-103335')?.addEventListener('click',applyTemplate);refresh();});
</script>
